package com.bplus.share;
import android.app.*;import android.content.*;import android.database.Cursor;import android.net.Uri;import android.os.*;import android.provider.*;import android.widget.*;import org.json.*;
public class LibraryActivity extends Activity {
 private FileSelection selection;private JSONArray visibleFiles=new JSONArray();private LinearLayout list;private String category="Videos";
 @Override protected void onCreate(Bundle b){super.onCreate(b);Ui.applyLocale(this);Ui.applyTheme(this);LinearLayout root=Ui.col(this);root.setBackgroundColor(Ui.bg);root.addView(Ui.topBar(this,getString(R.string.received_library),true,null));LinearLayout tabs=Ui.row(this);String[] folders={"Videos","Photos","Files"};int[] labels={R.string.library_videos,R.string.library_photos,R.string.library_files};for(int i=0;i<3;i++){final String folder=folders[i];TextView t=Ui.ghost(this,getString(labels[i]));Ui.pad(t,10,12,10,12,this);tabs.addView(t,Ui.lpw(1));t.setOnClickListener(v->{if(selection!=null)selection.back();category=folder;load();});}root.addView(tabs);ScrollView sc=new ScrollView(this);list=Ui.col(this);Ui.pad(list,20,10,20,15,this);sc.addView(list);root.addView(sc,Ui.lpW1());TextView old=Ui.ghost(this,getString(R.string.open_old_folder));Ui.pad(old,20,14,20,14,this);root.addView(old);old.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,91);});root.addView(Ui.t(this,getString(R.string.old_files_untouched),12,Ui.dim,App.cairoSB));setContentView(root);selection=new FileSelection(this,()->visibleFiles,this::load);}
 @Override protected void onResume(){super.onResume();if(list!=null)load();}
 private void load(){list.removeAllViews();visibleFiles=new JSONArray();try{java.util.LinkedHashMap<String,JSONObject> files=new java.util.LinkedHashMap<>();JSONArray saved=new JSONArray(Store.get("library","[]"));for(int i=0;i<saved.length();i++){JSONObject m=saved.optJSONObject(i);if(m!=null)files.put(m.optString("uri"),m);}JSONArray peers=Store.peers();for(int i=0;i<peers.length();i++){JSONArray messages=Store.thread(peers.getJSONObject(i).getString("id"));for(int j=0;j<messages.length();j++){JSONObject m=messages.getJSONObject(j);if(!m.optBoolean("me")&&m.optString("kind").equals("file")&&!m.optString("uri").isEmpty())files.put(m.optString("uri"),m);}}
 JSONArray groups=LocalGroups.all();for(int i=0;i<groups.length();i++){JSONArray t=Store.thread("live_"+groups.getJSONObject(i).getString("id"));for(int j=0;j<t.length();j++){JSONObject m=t.optJSONObject(j);if(m!=null&&!m.optBoolean("me")&&m.optString("kind").equals("file")&&!m.optString("uri").isEmpty())files.put(m.optString("uri"),m);}}
 int count=0;for(JSONObject m:files.values()){if(!Save.folder(m.optString("name")).equals(category))continue;visibleFiles.put(m);android.view.View card=FileCards.card(this,m,()->selection.toggle(m));card=selection.decorate(card,m);LinearLayout.LayoutParams lp=Ui.lp(-1,-2);lp.bottomMargin=Ui.dp(this,12);list.addView(card,lp);count++;}if(count==0)list.addView(Ui.t(this,getString(R.string.library_empty),14,Ui.dim,App.cairoSB));}catch(Exception e){list.addView(Ui.t(this,e.getClass().getSimpleName(),13,Ui.dim,App.cairoSB));}}
 @Override public void onBackPressed(){if(selection!=null&&selection.back())return;super.onBackPressed();}
 @Override protected void onActivityResult(int q,int r,Intent data){super.onActivityResult(q,r,data);if(q==91&&r==RESULT_OK&&data!=null){Uri u=data.getData();if(u==null)return;try{getContentResolver().takePersistableUriPermission(u,Intent.FLAG_GRANT_READ_URI_PERMISSION);String name="file";long size=0;try(Cursor c=getContentResolver().query(u,null,null,null,null)){if(c!=null&&c.moveToFirst()){int n=c.getColumnIndex(OpenableColumns.DISPLAY_NAME),s=c.getColumnIndex(OpenableColumns.SIZE);if(n>=0)name=c.getString(n);if(s>=0)size=c.getLong(s);}}JSONObject m=new JSONObject();m.put("kind","file");m.put("uri",u.toString());m.put("name",name);m.put("size",size);m.put("mime",Save.mime(name));FileCards.open(this,m);}catch(Exception e){Toast.makeText(this,getString(R.string.file_open_failed),1).show();}}}
}
